(function(){
  const rawWords = Array.isArray(RAW_DATA.words) ? RAW_DATA.words : [];
  const words = rawWords.map((e, idx) => {
    const items = Array.isArray(e.occurrences) ? e.occurrences.map(it => ({
      file: it.file || "",
      page: it.page || 1,
      snippet: it.context || it.snippet || ""
    })) : [];
    const files = new Set(items.map(x => x.file).filter(Boolean));
    const pages = new Set(items.map(x => String(x.file || "") + "::" + String(x.page || 1)));
    return {
      word: e.word || "",
      rank: e.rank ?? (idx + 1),
      freq: e.freq ?? 0,
      pdf_occurrences: e.indexedCount ?? items.length,
      docs: files.size,
      pages: pages.size,
      items
    };
  });

  const matchedWords = words.filter(w => (w.pdf_occurrences || 0) > 0).length;
  const totalOccurrences = words.reduce((sum, w) => sum + (Number(w.pdf_occurrences) || 0), 0);
  const pdfFiles = new Set();
  words.forEach(w => (w.items || []).forEach(it => {
    if (it.file) pdfFiles.add(it.file);
  }));

  window.WORD_DATA = words;
  window.SITE_STATS = {
    word_count: words.length,
    matched_words: matchedWords,
    total_occurrences: totalOccurrences,
    pdf_count: pdfFiles.size
  };
})();
